-- phase37b: load MedlinePlus definitions (5 files, 2026-11-05). Held for review: Carbohydrates, Enzymes, Folate, Sugar, Vitamin B12, Vitamin B6, Vitamin C, Vitamins
begin;
set local pc.change_source = 'medlineplus_definitions_2026-11-05';
create temp table _t(term text, kind text, attach_pcid bigint, mtype text) on commit drop;
do $$
declare r record; n6 bigint; n7 bigint; s text; p bigint;
begin
  select next_pcid into n6 from pcid_blocks where block_id=6 for update;
  select next_pcid into n7 from pcid_blocks where block_id=7 for update;
  for r in select * from _t where kind<>'attach' order by kind, term loop
    s := pc_slugify(r.term);
    if exists (select 1 from entities where slug=s) then raise exception 'slug collision: % (%)', s, r.term; end if;
    if r.kind='clinical' then p:=n6; n6:=n6+1; else p:=n7; n7:=n7+1; end if;
    if r.kind='clinical' then insert into clinical_concepts(pcid, concept_type, source_ref) values (p,'Health Term','MedlinePlus definitions 2026-11-05');
    else insert into measurements(pcid, measurement_type) values (p, r.mtype); end if;
    update _t set attach_pcid=p where term=r.term;
  end loop;
  update pcid_blocks set next_pcid=n6 where block_id=6;
  update pcid_blocks set next_pcid=n7 where block_id=7;
end $$;
create temp table _d(term text, file text, definition text, reference text, reference_url text, page_url text, last_updated date) on commit drop;
select t.attach_pcid, d.definition, d.reference, nullif(d.reference_url,''), 'medlineplus',
  'Definitions of Health Terms: '||case d.file when 'General' then 'General Health' else d.file end, d.page_url, d.last_updated
from _d d join _t t using(term);
commit;